    "weight": null,
    "key_characteristics": "patients with advanced cutaneous melanoma and immune-related hepatitis during immune checkpoint inhibitor therapy; steroid-refractory immune-related hepatitis; all received ipilimumab plus nivolumab; 27/28 patients were American Joint Committee on Cancer stage IV (8th edition); Eastern Cooperative Oncology Group performance status 0 in 75.0%; 27/28 patients developed severe immune-related hepatitis CTCAE grade 3 or 4; median time to onset of immune-related hepatitis was 46 days after first immune checkpoint inhibitor administration; 96.4% were initially treated with systemic corticosteroids"
  },
  "intervention": {
    "name": "infliximab",
    "dose": "5 mg/kg",
    "frequency": "22 patients received one dose; 6 patients received two doses",
