{
  "study": {
    "design": "controlled experimental study",
    "year": null,
    "sample_size": 16,
    "follow_up": "up to 4 weeks postpartum"
  },
  "population": {
    "age": null,
    "age_criteria": "periparturient / pregnant",
    "sex": "Female",
    "weight": null,
    "key_characteristics": "clinically healthy, pregnant Holstein cows"
  },
  "intervention": {
    "name": "Lipopolysaccharide (LPS) in saline solution",
    "dose": "0.01 µg/kg, 0.05 µg/kg, and 0.1 µg/kg body mass",
    "frequency": "Orally administered at 07:00 h on days -14, -10, -7, -3, 3, and 7 relative to parturition",
    "duration": "21 days (from day -14 to day 7 relative to parturition)"
  },
  "outcomes": [
    {
      "measure": "non-esterified fatty acids",
      "timepoint": "shortly before, and at 8 time-points up to 6 h post-challenge, and weekly up to 4 wk postpartum",
      "effect": "lowered (P < 0.01), particularly after the third LPS challenge",
      "ci": null
    },
    {
      "measure": "β-hydroxy-butyrate",
      "timepoint": "shortly before, and at 8 time-points up to 6 h post-challenge, and weekly up to 4 wk postpartum",
      "effect": "lowered (P < 0.01)",
      "ci": null
    },
    {
      "measure": "plasma glucose",
      "timepoint": "after the third oral LPS challenge",
      "effect": "tended to increase",
      "ci": null
    },
    {
      "measure": "Plasma calcium",
      "timepoint": "shortly before, and at 8 time-points up to 6 h post-challenge, and weekly up to 4 wk postpartum",
      "effect": "did not change",
      "ci": null
    },
    {
      "measure": "insulin",
      "timepoint": "shortly before, and at 8 time-points up to 6 h post-challenge, and weekly up to 4 wk postpartum",
      "effect": "greater (P < 0.01)",
      "ci": null
    },
    {
      "measure": "zinc",
      "timepoint": "shortly before, and at 8 time-points up to 6 h post-challenge, and weekly up to 4 wk postpartum",
      "effect": "greater (P < 0.01)",
      "ci": null
    },
    {
      "measure": "copper",
      "timepoint": "shortly before, and at 8 time-points up to 6 h post-challenge, and weekly up to 4 wk postpartum",
      "effect": "lower (P < 0.01)",
      "ci": null
    }
  ],
  "safety": null,
  "other_facts": "Control group received 3 ml of saline solution. Treatment group received 3 ml of saline solution containing LPS. Blood samples were measured shortly before, and at 8 different time-points after (up to 6 h), the first challenge of each LPS dosage to evaluate the post-challenge plasma profile. The authors recently showed that repeated oral exposure to LPS stimulated humoral immune responses in periparturient dairy cows. This is the first report to indicate a potential role for repeated oral administration of LPS around parturition to modulate the profile of plasma metabolites and minerals postpartum.",
  "summary": "Repeated oral administration of increasing doses of LPS around parturition in clinically healthy pregnant Holstein cows modulated postpartum plasma metabolites and minerals, significantly lowering non-esterified fatty acids, β-hydroxy-butyrate, and copper, while increasing insulin and zinc."
}

