    "sex": null,
    "weight": null,
    "key_characteristics": "Chronic hemodialysis patients; oligoanuric vs. normal diuresis; non-native fistula vs. native fistula; patients with cardiovascular events at baseline"
  },
  "intervention": {
    "name": "Hemodialysis using polysulfone dialyzers (high-flux and low-flux)",
    "dose": null,
    "frequency": "3 times weekly",
    "duration": "4-5 hours per session"
  },
  "outcomes": [
    {
      "measure": "cTNT level before hemodialysis",
      "timepoint": "baseline",
      "effect": "0.024 ng/ml (median)",
      "ci": null
    },
    {
      "measure": "NT-proBNP level before hemodialysis",
      "timepoint": "baseline",
      "effect": "4885 pg/ml (median)",
      "ci": null
    }
  ],
  "safety": null,
  "other_facts": "cTNT range: <0.001-0.703 ng/ml. Blood flow rates: 250-350 ml/min. Assay: third-generation cTNT assay (Elecsys Analyzer, Roche Diagnostics). NT-proBNP measured with polyclonal antibodies. Measurements taken twice with 6-week interval. Follow-up period: 42 months. Oligoanuric patients had significantly higher cTNT and NT-proBNP prior to dialysis (p<0.0001). cTNT and NT-proBNP increased significantly during hemodialysis sessions with low-flux dialyzer (p<0.0001) but remained unchanged with high-flux dialyzer. NT-proBNP increased markedly during low-flux dialysis (p<0.005). Patients with non-native fistula had significantly higher predialysis cTNT and NT-proBNP (p<0.05). Patients with cardiovascular events had significantly higher cTNT and NT-proBNP at baseline (p<0.05). Both biomarkers are of prognostic value for cardiovascular events and death.",
  "summary": "This study of 49 chronic hemodialysis patients found that cardiac biomarkers cTNT and NT-proBNP are elevated, increase during dialysis with low-flux but not high-flux dialyzers, and are associated with cardiovascular events and death over 42 months."
}

{
  "study": {
    "design": "retrospective review; Level III prognostic study",
    "year": "1982-2007",
    "sample_size": "37",
    "follow_up": "median 6 years 6 months (range, 11-211 months)"
  },
  "population": {
    "age": null,
    "age_criteria": null,
    "sex": null,
    "weight": null,
    "key_characteristics": "resectable high-grade osteosarcoma; nonmetastatic extremity osteosarcoma context"
  },
  "intervention": {
    "name": null,
    "dose": null,
    "frequency": null,
    "duration": null
  },
  "outcomes": [
    {
      "measure": "disease-free survival associated with Glut-1 expression",
      "timepoint": null,
      "effect": "relative risk 20.13; p=0.0016",
      "ci": "95% CI, 1.77-229.3"
    },
    {
      "measure": "CD34-positive microvessel density by Glut-1 expression",
      "timepoint": null,
      "effect": "Glut-1 positive mean±SD 26.5±19.4 vs Glut-1 negative mean±SD 46.4±35.3; Student's t-test p=0.038",
      "ci": null
    },
    {
      "measure": "association between Glut-1 expression and low microvessel density when high microvessel density was defined as >50",
      "timepoint": null,
      "effect": "positive Glut-1 expression was significantly associated with low microvessel density; chi-square test p=0.049",
      "ci": null
    }
  ],
  "safety": null,
  "other_facts": "Background: survival of patients with nonmetastatic extremity osteosarcoma has dramatically improved, but some patients do not respond to chemotherapy; Glut-1 is a key factor in glucose metabolism and has been reported as an independent prognostic factor in various tumors; little is known about the role of the Glut-1 pathway in osteosarcoma. Study questions: (1) whether Glut-1 expression is a prognostic marker for survival in osteosarcoma, and (2) whether there is a relationship between Glut-1 expression and tumor angiogenesis. Patients were excluded if representative biopsy material and followup data were not available. Glut-1 expression and the number of CD34-positive microvessels for angiogenic activity were measured immunohistochemically. Survival analyses were evaluated using the Kaplan-Meier method and the Cox proportional hazards model. The association between Glut-1 expression and microvessel density was analyzed using Student's t-test and chi-square test. Glut-1 expression was positive in 12/37 (32.4%) patients, with 4/37 (10.8%) showing strong expression. High microvessel density was defined as more than 50. Level of evidence: Level III, prognostic study.",
  "summary": "In a retrospective prognostic study of 37 patients with resectable high-grade osteosarcoma, Glut-1 expression was associated with shorter disease-free survival and lower CD34-positive microvessel density."
}

