{
  "study": {
    "design": "Bayesian post hoc analysis of a randomized clinical trial (MINT trial)",
    "year": "Recruitment April 26, 2017 to April 14, 2023; statistical analysis July 31, 2024 to February 18, 2026",
    "sample_size": "3504",
    "follow_up": "30 days"
  },
  "population": {
    "age": "mean (SD) age 72.1 (11.6) years",
    "age_criteria": "adults",
    "sex": "1911 of 3504 participants (54.5%) were men",
    "weight": null,
    "key_characteristics": "hospitalized with myocardial infarction and anemia"
  },
  "intervention": {
    "name": "restrictive transfusion strategy vs liberal transfusion strategy",
    "dose": "restrictive: transfuse if hemoglobin is <7 to 8 g/dL; liberal: maintain hemoglobin at >10 g/dL",
    "frequency": null,
    "duration": null
  },
  "outcomes": [
    {
      "measure": "30-day death or myocardial infarction (Bayesian posterior risk difference, liberal vs restrictive)",
      "timepoint": "30 days",
      "effect": "1.4% to 2.4% lower risk with the liberal strategy compared with the restrictive strategy, depending on prior beliefs",
      "ci": "95% credible interval -0.8% to 3.5% for the 1.4% lower risk estimate; 95% credible interval 0.3% to 4.6% for the 2.4% lower risk estimate"
    },
    {
      "measure": "probability that the liberal strategy was associated with a lower risk of 30-day death or myocardial infarction",
      "timepoint": "30 days",
      "effect": "89.1% to 98.8%",
      "ci": null
    },
    {
      "measure": "probability that the liberal strategy was associated with at least 1 less death or myocardial infarction per 100 treated",
      "timepoint": "30 days",
      "effect": "62.7% to 90.4%",
      "ci": null
    },
    {
      "measure": "heart failure (Bayesian posterior risk difference, liberal vs restrictive)",
      "timepoint": null,
      "effect": "0.2% to 0.6% higher risk with the liberal strategy compared with the restrictive strategy, depending on prior beliefs",
      "ci": "95% credible interval -1.6% to 1.2% for the 0.2% higher risk estimate; 95% credible interval -2.0% to 0.8% for the 0.6% higher risk estimate"
    },
    {
      "measure": "probability that the liberal strategy was associated with a higher risk of heart failure",
      "timepoint": null,
      "effect": "60.6% to 80.0%",
      "ci": null
    },
    {
      "measure": "probability that the liberal strategy was associated with at least 1 more heart failure event per 100 treated",
      "timepoint": null,
      "effect": "13.3% to 29.3%",
      "ci": null
    }
  ],
  "safety": [
    {
      "event": "heart failure",
      "rate": "0.2% to 0.6% higher risk with the liberal strategy compared with the restrictive strategy, depending on prior beliefs; probability of higher risk 60.6% to 80.0%; probability of at least 1 more heart failure event per 100 treated 13.3% to 29.3%"
    }
  ],
  "other_facts": "The Myocardial Ischemia and Transfusion (MINT) trial recruited adults hospitalized with myocardial infarction and anemia at 144 sites in 6 countries. Bayesian posterior risk differences were estimated using 3 prior beliefs: noninformative, liberal strategy superiority, and restrictive strategy superiority. The analysis also evaluated whether posterior probabilities exceeded predefined thresholds. Trial registration: ClinicalTrials.gov Identifier NCT02981407. The authors concluded that a liberal transfusion strategy was associated with a lower risk of 30-day death or myocardial infarction, outweighing the increased risk of heart failure, and that a liberal transfusion strategy may be reasonable consistent with guideline recommendations and according to patients' values and clinician risk assessment.",
  "summary": "In a Bayesian post hoc analysis of the MINT randomized clinical trial of adults with myocardial infarction and anemia, a liberal transfusion strategy was associated with a lower risk of 30-day death or myocardial infarction but a possible small increased risk of heart failure."
}

