{
  "study": {
    "design": "Retrospective cohort analysis",
    "year": null,
    "sample_size": "1476",
    "follow_up": "mean 7.3 years"
  },
  "population": {
    "age": "41-79 years",
    "age_criteria": "41-79 years",
    "sex": "937 males, 539 females",
    "weight": null,
    "key_characteristics": "Participants completed a maximal cycle cardiopulmonary exercise test; were not using medication with negative chronotropic effects; and did not have an implantable cardiac pacemaker."
  },
  "intervention": {
    "name": null,
    "dose": null,
    "frequency": null,
    "duration": null
  },
  "outcomes": [
    {
      "measure": "All-cause mortality",
      "timepoint": "mean follow-up 7.3 years",
      "effect": "44/1476 deaths (3.1%)",
      "ci": null
    },
    {
      "measure": "Death rate by exercise heart rate gradient score",
      "timepoint": "mean follow-up 7.3 years",
      "effect": "Inverse trend across exercise heart rate gradient scores (p < 0.05); death rate was 1.2% for score 10 and 13.5% for score 2",
      "ci": null
    },
    {
      "measure": "Age-adjusted hazard ratio for all-cause mortality for exercise heart rate gradient score 2",
      "timepoint": "mean follow-up 7.3 years",
      "effect": "3.53 (p = 0.011)",
      "ci": null
    },
    {
      "measure": "Age-adjusted hazard ratio for all-cause mortality for lowest quintile of heart rate reserve (<80 bpm)",
      "timepoint": "mean follow-up 7.3 years",
      "effect": "2.52 (p < 0.05)",
      "ci": null
    },
    {
      "measure": "Age-adjusted hazard ratio for all-cause mortality for lowest quintile of heart rate recovery (<27 bpm)",
      "timepoint": "mean follow-up 7.3 years",
      "effect": "2.57 (p < 0.05)",
      "ci": null
    }
  ],
  "safety": null,
  "other_facts": "Background: substantial evidence relates reduced exercise heart rate reserve and recovery to higher all-cause mortality risk, and a combined indicator had not been explored. Aim: to combine heart rate reserve and recovery into a single index and assess its utility to predict all-cause mortality. Heart rate reserve was calculated as heart rate maximum minus heart rate resting. Heart rate recovery was calculated as heart rate maximum minus heart rate at 1-minute post exercise. Heart rate reserve and recovery were divided into quintiles. Quintile rankings were summed to yield an exercise heart rate gradient ranging from 2 to 10, reflecting the magnitude of on- and off-heart rate transients to exercise. Survival analyses were undertaken using exercise heart rate gradient scores and heart rate reserve and recovery in the lowest quintiles. An exercise heart rate gradient score of 2 was a better predictor of all-cause mortality than either lowest quintile alone.",
  "summary": "In a retrospective cohort of 1476 adults undergoing maximal cycle exercise testing, a combined exercise heart rate gradient index predicted all-cause mortality better than low heart rate reserve or heart rate recovery alone over a mean 7.3-year follow-up."
}

