      "ci": null
    },
    {
      "measure": "Splenic noradrenergic innervation and norepinephrine content",
      "timepoint": "After 12 months of treatment",
      "effect": "Reduced in saline-treated tumor-bearing rats compared with young female rats without tumors; enhanced by deprenyl treatment",
      "ci": null
    },
    {
      "measure": "Splenic interleukin-2 and interferon-γ levels",
      "timepoint": "After 12 months of treatment",
      "effect": "Reduced in saline-treated tumor-bearing rats compared with young female rats without tumors; enhanced by 2.5 mg/kg deprenyl",
      "ci": null
    },
    {
      "measure": "Splenic natural killer cell activity",
      "timepoint": "After 12 months of treatment",
      "effect": "Reduced in saline-treated tumor-bearing rats compared with young female rats without tumors; enhanced by 2.5 mg/kg deprenyl",
      "ci": null
    },
