    },
    {
      "measure": "Hb-corrected TPMT activity in samples with low versus normal haemoglobin concentration",
      "timepoint": null,
      "effect": "83 versus 44 nmol 6-methyl thioguanine/g Hb/h; P < 0.0001",
      "ci": null
    },
    {
      "measure": "Reference interval for TPMT activity expressed in mU/L",
      "timepoint": null,
      "effect": "70-150 mU/L",
      "ci": null
    },
    {
      "measure": "Phenotype-genotype concordance",
      "timepoint": null,
      "effect": "88% with TPMT activity expressed in mU/L vs 89% with conventional approach",
      "ci": null
