      "effect": "97% (34/35); median = 5, IQR = 5-5",
      "ci": null
    },
    {
      "measure": "Construct validity: successful fetal head delivery",
      "timepoint": "During simulated scenarios",
      "effect": "Experts delivered the fetal head in 100% (36/36) of simulations; novices delivered the fetal head in 76.9% (30/39); p = 0.002",
